struct HeavyResource {};

// --- std::unique_ptr (Exclusive Ownership) ---

// Preferred creation (exception safe)
std::unique_ptr<HeavyResource> up1 = std::make_unique<HeavyResource>();

// No copy allowed (compile error)
// std::unique_ptr<HeavyResource> up2 = up1; 

// Transfer ownership via move
std::unique_ptr<HeavyResource> up3 = std::move(up1);

// Access raw pointer (use only if necessary)
HeavyResource* raw = up3.get();


// --- std::shared_ptr (Shared Ownership, Ref Counted) ---

std::shared_ptr<HeavyResource> sp1 = std::make_shared<HeavyResource>();

// Copy increases reference count (now 2)
std::shared_ptr<HeavyResource> sp2 = sp1;

// Access count
int count = sp1.use_count(); // 2


// --- std::weak_ptr (Non-Owning Reference) ---

std::weak_ptr<HeavyResource> wp = sp1;

// Must lock to access (if resource still exists)
if (auto locked_sp = wp.lock()) {
    locked_sp->do_work();
}
